INSERT INTO public.problema_cuadrante (id_problema, id_cuadrante, titulo, tipologia_punto_critico, delito_predominante, nivel_riesgo, cantidad_incidentes, radio_metros, lat, lng, geom, porque_1, porque_2, porque_3, porque_4, porque_5, causa_raiz, factores_ishikawa, actores_corresponsables, estado)
VALUES (1, 3, 'Foco Crítico #1: Agresiones/Amenazas (Cuadrante 3 - Sector Restrepo / Constructores / Malvinas)', 'facilitador_infracciones', 'Agresiones/Amenazas', 'CRÍTICO', 564, 3197, 1.614110, -75.605656, ST_GeomFromText('POINT(-75.605656 1.61411)', 4326), 'Alta recurrencia de hurtos y altercados en horas nocturnas sobre el corredor vial.', 'Deficiencia crítica de alumbrado público y tramos peatonales deteriorados.', 'Falta de mantenimiento oportuno de luminarias y poda de árboles que obstruyen la visibilidad.', 'Ausencia de reporte técnico articulado entre la comunidad y la concesión de alumbrado.', 'Carencia de intervención interinstitucional preventiva sobre el espacio físico del cuadrante.', 'Deterioro del entorno físico y déficit de iluminación pública que facilita el ocultamiento del infractor.', '{"entorno_fisico":"Luminarias averiadas y zonas verdes sin poda","dinamica_social":"Bajo flujo peatonal después de las 19:00 h","control_institucional":"Patrullaje concentrado en vías principales","oportunidad_delictiva":"Rutas de escape hacia callejones sin salida"}'::jsonb, 'Policía Nacional (DECAQ), Alcaldía de Florencia (Secretaría de Obras), Empresa de Alumbrado Público, JAC del sector', 'activo')
ON CONFLICT (id_problema) DO NOTHING;
INSERT INTO public.problema_cuadrante (id_problema, id_cuadrante, titulo, tipologia_punto_critico, delito_predominante, nivel_riesgo, cantidad_incidentes, radio_metros, lat, lng, geom, porque_1, porque_2, porque_3, porque_4, porque_5, causa_raiz, factores_ishikawa, actores_corresponsables, estado)
VALUES (2, 13, 'Foco Crítico #2: Piques (Cuadrante Rural R3 - Corregimiento San pedro)', 'generador_oportunidad', 'Piques', 'ALTO', 9, 834, 4.425585, -75.227248, ST_GeomFromText('POINT(-75.227248 4.425585)', 4326), 'Concentración elevada de hurtos por factor oportunidad y accidentes viales en horas pico.', 'Alta aglomeración de personas, motocicletas y comercio informal sobre la vía pública.', 'Invasión de andenes y parqueo estacionario sin regulación que reduce la visibilidad.', 'Desconocimiento ciudadano de medidas de autoprotección en zonas de alto flujo comercial.', 'Insuficiente regulación del espacio público y señalización preventiva en paraderos.', 'Afluencia masiva desordenada en zona comercial que genera oportunidades para el raponazo y siniestros viales.', '{"entorno_fisico":"Congestión vehicular e invasión de andenes","dinamica_social":"Comercio activo y descuido de objetos personales","control_institucional":"Requerimiento de apoyo de Tránsito Municipal","oportunidad_delictiva":"Alta densidad de víctimas potenciales en horas pico"}'::jsonb, 'Patrulla del Cuadrante, Secretaría de Tránsito y Movilidad, Cámara de Comercio de Florencia, Comerciantes', 'activo')
ON CONFLICT (id_problema) DO NOTHING;
INSERT INTO public.problema_cuadrante (id_problema, id_cuadrante, titulo, tipologia_punto_critico, delito_predominante, nivel_riesgo, cantidad_incidentes, radio_metros, lat, lng, geom, porque_1, porque_2, porque_3, porque_4, porque_5, causa_raiz, factores_ishikawa, actores_corresponsables, estado)
VALUES (3, 13, 'Foco Crítico #3: Robo (Cuadrante Rural R3 - Corregimiento San pedro)', 'atractor_infractores', 'Robo', 'ALTO', 6, 600, 4.414002, -75.232500, ST_GeomFromText('POINT(-75.2325 4.414002)', 4326), 'Reiteración de riñas, amenazas y maniobras peligrosas (piques) los fines de semana.', 'Concentración de establecimientos nocturnos y consumo de bebidas embriagantes en vía pública.', 'Incumplimiento de horarios de cierre y ocupación indebida de parques aledaños.', 'Tolerancia social frente al consumo en parques y convocatorias a piques clandestinos.', 'Falta de operativos conjuntos de control de establecimientos y espacio público.', 'Confluencia de venta/consumo de licor en espacio público y corredores usados para piques nocturnos.', '{"entorno_fisico":"Rectas viales sin reductores de velocidad y parques sin cerramiento","dinamica_social":"Consumo de alcohol y convocatorias nocturnas en redes","control_institucional":"Necesidad de caravanas interinstitucionales de seguridad","oportunidad_delictiva":"Intolerancia social asociada a estados de alicoramiento"}'::jsonb, 'Estación Florencia (DECAQ), Secretaría de Gobierno Municipal, Inspección de Policía, Seccional de Tránsito', 'activo')
ON CONFLICT (id_problema) DO NOTHING;
INSERT INTO public.problema_cuadrante (id_problema, id_cuadrante, titulo, tipologia_punto_critico, delito_predominante, nivel_riesgo, cantidad_incidentes, radio_metros, lat, lng, geom, porque_1, porque_2, porque_3, porque_4, porque_5, causa_raiz, factores_ishikawa, actores_corresponsables, estado)
VALUES (4, 13, 'Foco Crítico #4: Piques (Cuadrante Rural R3 - Corregimiento San pedro)', 'facilitador_infracciones', 'Piques', 'ALTO', 5, 530, 4.445152, -75.231181, ST_GeomFromText('POINT(-75.231181 4.445152)', 4326), 'Alta recurrencia de hurtos y altercados en horas nocturnas sobre el corredor vial.', 'Deficiencia crítica de alumbrado público y tramos peatonales deteriorados.', 'Falta de mantenimiento oportuno de luminarias y poda de árboles que obstruyen la visibilidad.', 'Ausencia de reporte técnico articulado entre la comunidad y la concesión de alumbrado.', 'Carencia de intervención interinstitucional preventiva sobre el espacio físico del cuadrante.', 'Deterioro del entorno físico y déficit de iluminación pública que facilita el ocultamiento del infractor.', '{"entorno_fisico":"Luminarias averiadas y zonas verdes sin poda","dinamica_social":"Bajo flujo peatonal después de las 19:00 h","control_institucional":"Patrullaje concentrado en vías principales","oportunidad_delictiva":"Rutas de escape hacia callejones sin salida"}'::jsonb, 'Policía Nacional (DECAQ), Alcaldía de Florencia (Secretaría de Obras), Empresa de Alumbrado Público, JAC del sector', 'activo')
ON CONFLICT (id_problema) DO NOTHING;
SELECT setval('public.problema_cuadrante_id_problema_seq', (SELECT MAX(id_problema) FROM public.problema_cuadrante));

INSERT INTO public.tamir_actividad (id_tamir, id_cuadrante, id_problema, semana_vigencia, dias_semana, franja_horaria, lugar_especifico, problematica_priorizada, actividad_preventiva, actores_apoyo, estado_cumplimiento, observacion_turno)
VALUES (1, 3, 1, 'Semana Vigente', 'Jueves, Viernes, Sábado y Domingo', '16:00 a 19:59', 'Radio de 3197m en Cuadrante 3 - Sector Restrepo / Constructores / Malvinas (1.61411, -75.605656)', 'Agresiones/Amenazas recurrente (564 casos - Riesgo CRÍTICO)', 'Realizar patrullaje preventivo disuasivo, verificación de puntos oscuros con la Junta de Acción Comunal y puestos de control rotativos.', 'Policía Nacional (DECAQ), Alcaldía de Florencia (Secretaría de Obras), Empresa de Alumbrado Público, JAC del sector', 'cumplida', 'Se realizó patrullaje focalizado, acercamiento comunitario y verificación de factores de riesgo en el punto crítico.')
ON CONFLICT (id_tamir) DO NOTHING;
