VALUES (2, 13, 2, 'Semana Vigente', 'Jueves, Viernes, Sábado y Domingo', '08:00 a 11:59', 'Radio de 834m en Cuadrante Rural R3 - Corregimiento San pedro (4.425585, -75.227248)', 'Piques recurrente (9 casos - Riesgo ALTO)', 'Presencia activa en corredor comercial, campañas puerta a puerta de prevención del hurto y despeje coordinado de puntos críticos.', 'Patrulla del Cuadrante, Secretaría de Tránsito y Movilidad, Cámara de Comercio de Florencia, Comerciantes', 'cumplida', 'Se realizó patrullaje focalizado, acercamiento comunitario y verificación de factores de riesgo en el punto crítico.')
ON CONFLICT (id_tamir) DO NOTHING;
INSERT INTO public.tamir_actividad (id_tamir, id_cuadrante, id_problema, semana_vigencia, dias_semana, franja_horaria, lugar_especifico, problematica_priorizada, actividad_preventiva, actores_apoyo, estado_cumplimiento, observacion_turno)
VALUES (3, 13, 3, 'Semana Vigente', 'Jueves, Viernes, Sábado y Domingo', '20:00 a 23:59', 'Radio de 600m en Cuadrante Rural R3 - Corregimiento San pedro (4.414002, -75.2325)', 'Robo recurrente (6 casos - Riesgo ALTO)', 'Instalación de puesto de control preventivo sobre corredor vial, registro a motocicletas y verificación de establecimientos abiertos al público.', 'Estación Florencia (DECAQ), Secretaría de Gobierno Municipal, Inspección de Policía, Seccional de Tránsito', 'en_ejecucion', '')
