-- 7. ASIGNACIÓN RETROACTIVA DE CUADRANTES A INCIDENTES EXISTENTES
UPDATE public.incidente i SET id_cuadrante = c.id_cuadrante FROM public.cuadrante c WHERE i.id_cuadrante IS NULL AND i.geom IS NOT NULL AND ST_Intersects(c.geom, i.geom);

COMMIT;
